from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(17,'symetrie','La symétrie, axes droits et obliques','4 · Espace et géométrie',
'Axes · Quadrillage · Diagonales · Figures complétées',
['Reconnaître les axes de symétrie d’une figure.','Construire un symétrique sur quadrillage, axe horizontal ou vertical.','Construire un symétrique le long d’une diagonale du quadrillage.'],
['Symétrie du CM1 sur axes horizontaux et verticaux.'],[
page(1,'Les acquis, consolidés',
bloc('definition',r'Une droite est un axe de symétrie d’une figure si le pliage le long de cette droite superpose exactement les deux parties. Le carré a 4 axes, le rectangle 2, le triangle équilatéral 3, le cercle une infinité.'),
r'@FIG:cours-symetrie@',
bloc('savoirfaire',r'Axe vertical ou horizontal : le symétrique d’un point se place de l’autre côté, à autant de carreaux de l’axe, sur la même ligne ou la même colonne. Un point de l’axe ne bouge pas.','Compter les carreaux'),
bloc('propriete',r'La symétrie conserve les longueurs, les angles et les aires : le symétrique d’un segment de 5 carreaux mesure 5 carreaux ; celui d’un carré reste un carré superposable.')),
page(2,'L’axe en diagonale',
bloc('definition',r'Sur un quadrillage, une diagonale des carreaux peut servir d’axe : c’est la droite qui traverse les carreaux de coin en coin, à 45 degrés.'),
r'@FIG:cours-diagonale@',
bloc('savoirfaire',r'Avec un axe diagonal, les déplacements s’échangent : un point situé à 2 carreaux à droite de l’axe, en comptant perpendiculairement par les diagonales des carreaux, se reflète à 2 carreaux de l’autre côté. En pratique : un trajet « 3 vers la droite » devient « 3 vers le haut », et réciproquement, quand l’axe monte vers la droite.','Échanger les directions'),
bloc('exemple',r'Le symétrique du point situé 3 carreaux à droite et 1 carreau au-dessus d’un point de l’axe est le point situé 1 carreau à droite et 3 carreaux au-dessus : les deux nombres s’échangent.'),
bloc('attention',r'Contrôler au calque : plié le long de la diagonale, le quadrillage se superpose à lui-même, et la figure doit tomber sur son image. Un point de l’axe reste immobile, comme toujours.'))
],[
E('Combien d’axes ?',r'Donner le nombre d’axes de symétrie de chaque figure dessinée : carré, rectangle, triangle équilatéral, cercle.',r'Carré : $\res4$ ; rectangle : $\res2$ ; triangle équilatéral : $\res3$ ; cercle : $\res{\text{une infinité}}$ d’axes, tous ses diamètres.','Tester médianes et diagonales par pliage mental.','assert 4>3>2',figure='sym-1'),
E('Axe vertical',r'Construire le symétrique de la figure par rapport à l’axe vertical tracé.',r'Chaque sommet traverse l’axe à même distance, sur sa ligne ; l’image, en vert, reproduit la figure retournée.','Compter les carreaux jusqu’à l’axe.','assert 1==1',figure='sym-2'),
E('Axe horizontal',r'Construire le symétrique du drapeau par rapport à l’axe horizontal.',r'Les points descendent sous l’axe à égale distance, colonne par colonne ; le pied du mât, posé sur l’axe, reste en place. L’image figure en vert.','Refléter colonne par colonne.','assert 1==1',figure='sym-3'),
E('Le point sur la diagonale',r'L’axe est la diagonale tracée. Placer le symétrique de chacun des trois points marqués.',r"Les déplacements s’échangent : le point à (3 ; 1) d’un point de l’axe va en (1 ; 3). Les trois images figurent en vert : $A'(1 ; 3)$, $B'(2 ; 5)$ et $C'(0 ; 4)$.",'Échanger « vers la droite » et « vers le haut ».','assert (3,1)!=(1,3)',figure='sym-4'),
E('Segment et diagonale',r'Construire le symétrique du segment [AB] par rapport à la diagonale tracée.',r"A(2 ; 0) va en A'(0 ; 2) et B(3 ; 2) va en B'(2 ; 3), en comptant depuis le pied de l’axe : le segment image, vert, a la même longueur que [AB].",'Traiter chaque extrémité puis joindre.','assert 1==1',figure='sym-5'),
E('La figure oblique',r'Compléter la figure pour que la diagonale soit son axe de symétrie.',r'Chaque case colorée a sa jumelle obtenue en échangeant les deux directions le long de l’axe ; les cases ajoutées figurent en vert.','Associer les cases deux par deux à travers la diagonale.','assert 1==1',figure='sym-6'),
E('Chercher l’erreur',r"Noa a tracé le symétrique du triangle par rapport à la diagonale, mais un sommet est faux. Lequel ? Corriger.",r"Le sommet $\res{C'}$ est placé en (2 ; 5) ; or C(5 ; 1) doit donner C'(1 ; 5), en échangeant ses deux coordonnées. Le point corrigé figure en vert.",'Vérifier chaque sommet par l’échange des écarts.','assert (5,1)[::-1]==(1,5) and (1,5)!=(2,5)',figure='sym-7'),
E('Les lettres au miroir',r'Parmi les lettres N, S, Z dessinées, aucune n’a d’axe de symétrie, et pourtant elles semblent « symétriques ». Expliquer.',r'Ces lettres se superposent à elles-mêmes après un demi-tour, pas par pliage : elles ont un centre de symétrie, pas un axe. Le pliage, lui, échoue : $\res{\text{aucun axe}}$. La symétrie axiale exige le pliage.','Tester le pliage, pas la rotation.','assert 1==1',figure='sym-8'),
E('Deux axes perpendiculaires',r'Compléter la figure pour qu’elle admette l’axe vertical et l’axe horizontal tracés.',r'On reflète d’abord à travers l’axe vertical, puis tout le résultat à travers l’horizontal : la figure finale montre 4 quarts identiques, ajoutés en vert.','Enchaîner les deux reflets.','assert 4==4',figure='sym-9'),
E('Les longueurs conservées',r'Le segment [RS] mesure 4 carreaux le long du quadrillage. Sans mesurer, donner la longueur de son symétrique par rapport à la diagonale, puis contrôler sur la construction.',r'La symétrie conserve les longueurs : l’image mesure $\res4$ carreaux, désormais comptés dans l’autre direction. La construction verte le confirme.','Citer la conservation des longueurs.','assert 4==4',figure='sym-10'),
E('Le logo du club',r'Compléter le logo pour que la diagonale tracée soit un axe de symétrie, en coloriant les cases utiles.',r'Chaque case colorée se reflète en échangeant ses écarts à l’axe : $\res5$ cases sont à colorier, en vert au corrigé.','Compter les cases restantes après pliage mental.','assert 5==5',figure='sym-11'),
E('Le pavage malin',r'Sur le quadrillage, la frise se poursuit par symétries successives d’axes verticaux régulièrement espacés. Dessiner le motif suivant.',r'Chaque axe renvoie le motif précédent retourné : le motif suivant, en vert, regarde dans l’autre sens. Les frises alternent ainsi endroit et envers.','Appliquer l’axe le plus proche au dernier motif.','assert 1==1',figure='sym-12'),
E('Axe à trouver',r'La figure complète admet un axe de symétrie : le tracer, puis justifier au calque.',r'L’axe est la $\res{\text{diagonale}}$ qui échange les deux moitiés ; plié le long d’elle, le calque superpose exactement la figure. Tout autre pli déborde.','Chercher le pli qui superpose les moitiés.','assert 1==1',figure='sym-13'),
E('La rosace du vitrail',r'Le quart de rosace est dessiné ; les deux axes, vertical et horizontal, sont tracés. Compléter la rosace et dire combien de cases colorées compte la figure finale.',r'Chaque reflet multiplie les cases : le quart en compte 6, la rosace complète $6\times4=\res{24}$ cases, ajoutées en vert.','Compter un quart puis multiplier par quatre.','assert 6*4==24',figure='sym-14'),
E('Vrai ou faux ?',r'« Le symétrique d’un carré peut être un rectangle non carré. » « Un point de l’axe est son propre symétrique. » Justifier.',r'Première phrase : $\res{\text{faux}}$, la symétrie conserve longueurs et angles, l’image d’un carré est un carré superposable. Seconde : $\res{\text{vrai}}$, un point de l’axe ne bouge pas au pliage.','S’appuyer sur les propriétés de conservation.','assert 1==1',figure='sym-15')
],reperes=['Axes et figures usuelles','Axes verticaux et horizontaux','L’axe en diagonale','Conservations et pavages'],deco='geometrie')

chapitre(18,'solides','Solides : cubes, pavés et patrons','4 · Espace et géométrie',
'Descriptions · Patrons du cube et du pavé · Assemblages',
['Décrire les solides usuels par leurs faces, arêtes et sommets.','Reconnaître et construire des patrons du cube, reconnaître ceux du pavé.','Dénombrer des cubes et coder des déplacements.'],
['Solides et patron du cube vus au CM1.'],[
page(1,'Décrire sans se tromper',
bloc('definition',r'Les solides usuels : cube, pavé, boule, cylindre, cône, pyramide, prisme droit. Un polyèdre n’a que des faces plates ; on le décrit par le nombre et la nature de ses faces, arêtes et sommets.'),
r'@FIG:cours-solides@',
bloc('propriete',r'Cube : 6 faces carrées, 12 arêtes, 8 sommets. Pavé : 6 faces rectangulaires, faces opposées identiques. Pyramide : une base et des faces latérales triangulaires. Prisme droit : deux bases superposables reliées par des rectangles.'),
bloc('attention',r'En perspective, les faces cachées existent : les arêtes invisibles se dessinent en pointillés. Justifier un nom de solide par ses propriétés, jamais par l’allure du dessin.')),
page(2,'Patrons du cube et du pavé',
bloc('definition',r'Un patron, mis à plat d’un seul tenant, se replie en solide sans superposition. Un patron de cube réunit 6 carrés ; un patron de pavé réunit 6 rectangles, identiques deux à deux.'),
r'@FIG:cours-patron-pave@',
bloc('savoirfaire',r'Tester un patron de pavé : repérer les trois paires de faces (dessus-dessous, devant-derrière, gauche-droite) ; les faces d’une même paire ne se touchent pas sur le patron, et les dimensions des bords pliés ensemble coïncident.','Les trois paires de faces'),
bloc('exemple',r'Dans un patron de cube en croix, les faces opposées sont séparées par une face. Sur un patron de pavé, un rectangle de 5 sur 3 ne peut pas se plier contre un bord de 2 : les longueurs des bords communs doivent être égales.'))
],[
E('Nommer les solides',r'Nommer les six solides dessinés et entourer ceux qui sont des polyèdres.',r'Cube, pavé, cylindre, pyramide, cône, boule. Les polyèdres, aux faces toutes plates : $\res{\text{cube, pavé, pyramide}}$ — le cylindre, le cône et la boule ont des surfaces courbes.','Chercher les faces planes uniquement.','assert 3+3==6',figure='sol-1'),
E('Compter sur le cube',r'Donner le nombre de faces, d’arêtes et de sommets du cube, puis du pavé.',r'Tous deux ont $\res6$ faces, $\res{12}$ arêtes et $\res8$ sommets : carrées pour le cube, rectangulaires pour le pavé.','Compter aussi les éléments cachés.','assert 6+12+8==26',figure='sol-2'),
E('Le prisme à base triangulaire',r'Décrire le prisme droit dessiné : bases, autres faces, arêtes et sommets.',r'Deux bases $\res{\text{triangulaires}}$ superposables, trois faces $\res{\text{rectangulaires}}$, 9 arêtes et 6 sommets.','Repérer d’abord les deux bases jumelles.','assert 2+3==5 and 9==9 and 6==6',figure='sol-3'),
E('La pyramide',r'La pyramide dessinée a une base carrée. Donner le nombre de ses faces, arêtes et sommets.',r'Une base carrée et 4 faces triangulaires : $\res5$ faces, $\res8$ arêtes et $\res5$ sommets, dont le sommet principal.','Séparer base et faces latérales.','assert 4+1==5 and 8==8 and 4+1==5',figure='sol-4'),
E('Patron de cube ?',r'Parmi les trois dispositions de six carrés, lesquelles sont des patrons de cube ?',r'La croix et la forme en T se replient sans superposition : $\res{\text{patrons}}$. La disposition contenant un bloc carré de quatre cases superpose deux faces : $\res{\text{pas un patron}}$.','Plier mentalement face après face.','assert 6==6',figure='sol-5'),
E('Les faces opposées',r'Sur le patron en croix, quelle face se retrouve opposée à la face A ? Et à la face E ?',r'Les faces opposées sont séparées par une face sur le patron : l’opposée de A est $\res C$, celle de E est $\res F$.','Sauter une face dans l’alignement.','assert 1==1',figure='sol-6'),
E('Patron de pavé ?',r'Parmi les deux dispositions de six rectangles, laquelle est un patron de pavé ? Justifier par les paires de faces.',r'La disposition 1 réunit bien $\res{\text{trois paires}}$ de rectangles identiques, bords communs de même longueur : c’est un patron. Dans la 2, deux bords pliés ensemble ont des longueurs différentes : le pliage bâille.','Comparer les bords qui se rejoignent.','assert 3*2==6',figure='sol-7'),
E('Le patron du dé',r'Les faces opposées d’un dé totalisent 7. Compléter le patron : 1, 2 et 3 sont placés. Où écrire 4, 5 et 6 ?',r'L’opposée de 3 porte $\res4$, celle de 2 porte $\res5$, celle de 1 porte $\res6$ : les valeurs, en vert, respectent les paires séparées d’une face.','Former les paires qui totalisent 7.','assert 3+4==2+5==1+6==7',figure='sol-8'),
E('Construire le patron',r'Tracer un patron d’un pavé de 4 cm sur 2 cm sur 1 cm. Combien de rectangles de chaque taille faut-il ?',r'Trois paires : deux faces de $4\times2$, deux de $4\times1$, deux de $2\times1$. Le patron, en vert à échelle réduite, aligne ces six rectangles en respectant les bords communs.','Prévoir les trois paires avant de tracer.','assert 2+2+2==6',figure='sol-9'),
E('Les cubes cachés',r'Compter les cubes de l’assemblage, cubes cachés compris.',r'Étage du bas : $4\times2=8$ ; étage du milieu : 4 ; étage du haut : 2. Total : $8+4+2=\res{14}$ cubes, porteurs cachés comptés.','Compter étage par étage.','assert 8+4+2==14',figure='sol-10'),
E('La bonne vue',r'Associer à l’assemblage sa vue de face et sa vue de dessus parmi les trois vignettes.',r'La vue de face lit les hauteurs des colonnes : vignette $\res2$. La vue de dessus lit les cases occupées au sol : vignette $\res1$. La vignette 3 ne correspond à aucun point de vue.','Imaginer chaque point de vue séparément.','assert 2!=1',figure='sol-11'),
E('Compléter le grand cube',r'L’assemblage compte 20 cubes. Combien en manque-t-il pour former un grand cube de 3 cubes de côté ?',r'Le grand cube contient $3\times3\times3=27$ cubes : il manque $27-20=\res7$ cubes.','Calculer le volume visé en cubes.','assert 3**3==27 and 27-20==7',figure='sol-12'),
E('Coder le chemin',r'Écrire la suite d’instructions menant le pion du départ au but en suivant le chemin dessiné (avancer, pivoter à droite ou à gauche).',r'Un codage correct : avancer de 3 ; pivoter à gauche ; avancer de 2 ; pivoter à droite ; avancer de 2 ; pivoter à droite ; avancer de 2. Les quarts de tour suivent l’orientation $\res{\text{du pion}}$, pas celle du lecteur.','Mettre à jour l’orientation à chaque virage.','assert 3+2+2+2==9',figure='sol-13'),
E('Exécuter le programme',r'Le pion part de la case marquée, tourné vers la droite de la feuille. Exécuter : avancer de 4 ; pivoter à gauche ; avancer de 2 ; pivoter à gauche ; avancer de 4 ; pivoter à gauche ; avancer de 2. Où arrive-t-il ?',r'Le chemin dessine un rectangle de 4 cases sur 2 : le pion revient $\res{\text{à sa case de départ}}$, désormais tourné vers le bas de la feuille. Contrôle : deux côtés de 4, deux côtés de 2, trois quarts de tour à gauche.','Suivre le rectangle case par case.','assert (0,0)==(0,0)',figure='sol-14'),
E('Le cube peint',r'Un cube de 3 sur 3 sur 3, fait de 27 petits cubes, est peint sur toutes ses faces. Combien de petits cubes ont exactement 2 faces peintes ? Et aucune ?',r'Deux faces peintes : les cubes du milieu des arêtes, $\res{12}$. Aucune : le cube central, $\res1$. Contrôle : $8$ coins $+12+6$ centres de faces $+1=27$.','Classer les cubes selon leur position.','assert 8+12+6+1==27',figure='sol-15')
],reperes=['Descriptions des solides','Patrons du cube','Patrons du pavé','Assemblages et déplacements'],deco='espace')
